sql.ricochetWebhook.getCompanyCountryIdByCom:
with company_country as (
  select cc.id id
  from flow.company_country cc
  where cc.company_id = 3
)
select (case when (select id from company_country) is not null then (select id from company_country) else null::integer end) company_country_id;

sql.ricochetWebhook.insertLead:
insert into flow.contact (contact_type_id, first_name, last_name, mobile, email, street1, city, postal_code, created_by_id, company_id, owner_user_position_id, company_state_id, company_country_id)
values (2, :firstName, :lastName, :mobile, :email, :street1, :city, :postalCode, :leadOwnerUserId, 3, :leadOwnerUserPositionId, :companyStateId::integer, :companyCountryId::integer)
returning id;
